def solve(inputs: dict) -> float:
    M = inputs['M']
    power = inputs['power']
    mod = inputs['mod']

    # Convert to list of lists if needed
    if not isinstance(M, list):
        M = M.tolist()

    n = len(M)

    def matrix_mult(A, B, mod):
        """Multiply two n×n matrices modulo mod"""
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_pow(M, p, mod):
        """Compute M^p mod mod using binary exponentiation"""
        # Initialize result as identity matrix
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            result[i][i] = 1

        base = [row[:] for row in M]  # Copy M

        while p > 0:
            if p % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            p //= 2

        return result

    result_matrix = matrix_pow(M, power, mod)

    # Sum all entries
    total = 0
    for i in range(n):
        for j in range(n):
            total += result_matrix[i][j]

    return float(total % mod)

